"""Three user-defined polygon transitions; no geometry is generated by code."""

import logging
from collections import Counter
from dataclasses import dataclass
from typing import Literal
from uuid import uuid4

import cv2
import numpy as np
from pydantic import Field, model_validator

from workledger.schemas import Strict

from .zones import orientation, validate_polygon

logger = logging.getLogger("uvicorn.error.workledger.door.crossing")


class DoorPolygon(Strict):
    role: Literal["a", "transition", "b"]
    name: str = Field(min_length=1, max_length=80)
    points: list[list[float]]

    @model_validator(mode="after")
    def valid(self):
        validate_polygon(self.points)
        return self


class DoorZoneInput(Strict):
    expected_version: int = Field(default=0, ge=0)
    active: bool = True
    name: str = Field(min_length=1, max_length=100)
    zones: list[DoorPolygon] = Field(min_length=3, max_length=3)
    entry_forward: bool = True
    anchor: Literal["foot", "torso"] = "foot"
    inertia: int = Field(default=2, ge=2, le=10)
    stable_ms: int = Field(default=100, ge=50, le=2000)
    max_gap_ms: int = Field(default=750, ge=100, le=1500)
    traversal_ms: int = Field(default=10000, ge=1000, le=30000)
    cooldown_ms: int = Field(default=1500, ge=0, le=10000)
    verification_wait_ms: int = Field(default=5000, ge=0, le=10000)

    @model_validator(mode="after")
    def valid(self):
        if {z.role for z in self.zones} != {"a", "transition", "b"}:
            raise ValueError("Draw exactly one A, Transition and B polygon")
        for i, left in enumerate(self.zones):
            a = np.asarray(left.points, np.float32)
            for right in self.zones[i + 1 :]:
                b = np.asarray(right.points, np.float32)
                # Shared boundaries are allowed; intersecting interiors are not.
                for polygon, other in ((a, b), (b, a)):
                    for j, p in enumerate(polygon):
                        q = polygon[(j + 1) % len(polygon)]
                        edge = q - p
                        normal = np.array([-edge[1], edge[0]])
                        normal = normal / max(float(np.linalg.norm(normal)), 1e-9) * 1e-5
                        probes = (p, (p + q) / 2, (p + q) / 2 + normal, (p + q) / 2 - normal)
                        if any(
                            cv2.pointPolygonTest(a, tuple(map(float, v)), False) > 0
                            and cv2.pointPolygonTest(b, tuple(map(float, v)), False) > 0
                            for v in probes
                        ):
                            raise ValueError("Door polygon interiors must not overlap")
                        for k, c in enumerate(other):
                            d = other[(k + 1) % len(other)]
                            if (
                                orientation(p, q, c) * orientation(p, q, d) < 0
                                and orientation(c, d, p) * orientation(c, d, q) < 0
                            ):
                                raise ValueError("Door polygons must not cross")
        return self


@dataclass
class Passage:
    seen: float = -1e9
    candidate: str | None = None
    candidate_at: float = 0
    hits: int = 0
    stable: str | None = None
    origin: str | None = None
    started: float = 0
    transitioned: bool = False
    identity_safe: bool = True


class DoorCrossingEngine:
    def __init__(self):
        self.epochs = {}
        self.states = {}
        self.pending = {}
        self.cooldowns = {}
        self.diagnostics = {}

    def note(self, camera, track, reason, **details):
        diagnostic = self.diagnostics.setdefault(camera, {"tracks": {}, "counts": Counter()})
        diagnostic.setdefault("tracks", {})
        diagnostic.setdefault("counts", Counter())
        previous = diagnostic["tracks"].get(str(track), {})
        if previous.get("reason") != reason:
            diagnostic["counts"][reason] += 1
            logger.debug("Door camera=%s track=%s reason=%s", camera, track, reason)
        diagnostic["tracks"][str(track)] = {"track_id": str(track), "reason": reason, **details}
        while len(diagnostic["tracks"]) > 30:
            diagnostic["tracks"].pop(next(iter(diagnostic["tracks"])))

    @staticmethod
    def verification_reason(observation, at):
        if not observation.get("identity_reliable", True):
            return "identity_association_ambiguous"
        if not observation.get("employee_id"):
            return "identity_not_locked"
        if observation.get("attendance_employee_id") != observation["employee_id"]:
            return "no_qualifying_face_match"
        if observation.get("hits", 0) < observation.get("required_hits", 3):
            return "insufficient_face_confirmations"
        if observation.get("needs_reverification"):
            return "identity_needs_reverification"
        if not 0 <= at - observation.get("attendance_verified_at", -1e9) <= 5:
            return "face_evidence_expired"
        return "verified"

    def observe(self, camera, config, observations, at):
        epoch = (config["id"], config["version"])
        changes = []
        if self.epochs.get(camera) != epoch:
            self.diagnostics.pop(camera, None)
            self.states = {key: value for key, value in self.states.items() if key[0] != camera}
            for key, event in list(self.pending.items()):
                if event["camera_id"] == camera:
                    event.update(
                        status="review", reason="Zone geometry changed before verification"
                    )
                    changes.append(dict(event))
                    del self.pending[key]
            self.epochs[camera] = epoch
        if not config.get("active"):
            self.note(camera, "camera", "configuration_disabled", at=at)
            return changes
        # A save never reinterprets a frame captured before that save.
        if at < config.get("effective_at", 0):
            self.note(camera, "camera", "frame_predates_saved_geometry", at=at)
            return changes
        if not observations:
            self.note(camera, "camera", "no_body_tracks", at=at)
        else:
            self.diagnostics.get(camera, {}).get("tracks", {}).pop("camera", None)
        polygons = {
            zone["role"]: np.asarray(zone["points"], np.float32) for zone in config["zones"]
        }
        by_track = {str(o["track_id"]): o for o in observations}
        for event in list(self.pending.values()):
            if event["camera_id"] != camera:
                continue
            current = by_track.get(event["track_id"])
            employee = current.get("employee_id") if current else None
            if (
                at <= event["deadline"]
                and current
                and self.verified(current, at)
                and event.get("employee_id") in (None, employee)
            ):
                event.update(
                    status="confirmed",
                    employee_id=employee,
                    reason="Verified tracked crossing",
                    confidence=current.get("confidence"),
                )
                changes.append(dict(event))
                del self.pending[event["id"]]
            elif at > event["deadline"]:
                event.update(
                    status="review",
                    reason="No qualifying face verification within the crossing window",
                )
                changes.append(dict(event))
                del self.pending[event["id"]]
        for observation in observations:
            key = (camera, str(observation["track_id"]))
            state = self.states.setdefault(key, Passage())
            if at <= state.seen:
                continue
            if not observation.get("reliable") or at - state.seen > config["max_gap_ms"] / 1000:
                state = Passage()
                self.states[key] = state
            state.seen = at
            if not observation.get("reliable"):
                self.note(camera, key[1], "body_anchor_unreliable", at=at)
                continue
            point = observation.get(config["anchor"])
            if point is None:
                self.note(camera, key[1], "selected_anchor_missing", at=at)
                continue
            found = [
                name
                for name, polygon in polygons.items()
                if cv2.pointPolygonTest(polygon, tuple(point), False) > 0
            ]
            zone = found[0] if len(found) == 1 else None
            if state.origin and not observation.get("identity_reliable", True):
                state.identity_safe = False
            if zone != state.candidate:
                state.candidate, state.candidate_at, state.hits = zone, at, 1
            else:
                state.hits += 1
            reason = (
                "outside_zones"
                if zone is None
                else "zone_dwell_pending"
                if state.hits < config["inertia"]
                or at - state.candidate_at + 1e-6 < config["stable_ms"] / 1000
                else "waiting_for_start_side"
                if state.origin is None and zone == "transition"
                else "waiting_for_destination"
                if state.transitioned and zone == "transition"
                else "waiting_for_transition"
            )
            self.note(
                camera,
                key[1],
                reason,
                at=at,
                point=point,
                zone=zone,
                origin=state.origin,
                transitioned=state.transitioned,
                verification=self.verification_reason(observation, at),
                observed_hits=state.hits,
            )
            if (
                zone is None
                or state.hits < config["inertia"]
                or at - state.candidate_at + 1e-6 < config["stable_ms"] / 1000
            ):
                continue
            if zone == state.stable:
                continue
            state.stable = zone
            logger.info("Door camera=%s track=%s stable_zone=%s", camera, key[1], zone)
            if state.transitioned and at - state.started > config["traversal_ms"] / 1000:
                state.origin = None
                state.transitioned = False
            if zone == "transition":
                if state.origin:
                    if not state.transitioned:
                        state.started = state.candidate_at
                    state.transitioned = True
            elif state.origin is None or zone == state.origin:
                state.origin = zone
                state.started = at
                state.transitioned = False
                state.identity_safe = observation.get("identity_reliable", True)
            elif state.transitioned:
                forward = state.origin == "a" and zone == "b"
                kind = "entry" if forward == config["entry_forward"] else "exit"
                employee = observation.get("employee_id")
                cooldown = (camera, employee or key[1], kind)
                if at - self.cooldowns.get(cooldown, -1e9) >= config["cooldown_ms"] / 1000:
                    event = {
                        "id": str(uuid4()),
                        "zone_id": config["id"],
                        "zone_version": config["version"],
                        "camera_id": camera,
                        "company_id": config["company_id"],
                        "site_id": config["site_id"],
                        "track_id": key[1],
                        "employee_id": employee,
                        "kind": kind,
                        "occurred_at": state.candidate_at,
                        "status": (
                            "review"
                            if not state.identity_safe
                            else "confirmed"
                            if self.verified(observation, at)
                            else "pending"
                        ),
                        "deadline": at + config["verification_wait_ms"] / 1000,
                        "anchor": config["anchor"],
                        "reason": (
                            "identity_association_ambiguous_during_traversal"
                            if not state.identity_safe
                            else "verified"
                            if self.verified(observation, at)
                            else self.verification_reason(observation, at)
                        ),
                        "confidence": observation.get("confidence"),
                        "door_name": config["name"],
                    }
                    changes.append(dict(event))
                    if event["status"] == "pending":
                        self.pending[event["id"]] = event
                    self.cooldowns[cooldown] = at
                    self.note(
                        camera,
                        key[1],
                        event["status"] + "_crossing",
                        at=at,
                        kind=kind,
                        verification=event["reason"],
                        point=point,
                        zone=zone,
                    )
                else:
                    self.note(
                        camera, key[1], "same_direction_cooldown", at=at, point=point, zone=zone
                    )
                state.origin = zone
                state.started = at
                state.transitioned = False
                state.identity_safe = observation.get("identity_reliable", True)
            else:
                state.origin = zone
                state.started = at
                state.transitioned = False
                state.identity_safe = observation.get("identity_reliable", True)
        self.states = {
            key: value
            for key, value in self.states.items()
            if key[0] != camera or at - value.seen < 30
        }
        self.cooldowns = {key: value for key, value in self.cooldowns.items() if at - value < 60}
        return changes

    @staticmethod
    def verified(observation, at):
        return bool(
            observation.get("reliable")
            and observation.get("identity_reliable", True)
            and observation.get("employee_id")
            and observation.get("attendance_employee_id") == observation["employee_id"]
            and observation.get("hits", 0) >= observation.get("required_hits", 3)
            and not observation.get("needs_reverification")
            and 0 <= at - observation.get("attendance_verified_at", -1e9) <= 5
        )
